            id,
            state: match str_at(event, "/status").as_deref() {
                Some("failed") => SubagentState::Failed,
                Some("stopped" | "killed" | "cancelled") => SubagentState::Stopped,
                _ => SubagentState::Completed,
            },
        }),
        _ => None,
    }
}

